    for f in pr["files"]:
        files_to_prs[f["path"]].append(pr["number"])

print("Files touched by multiple Dependabot PRs:")
for path, pr_list in sorted(files_to_prs.items()):
    if len(pr_list) > 1:
        print(f"  {path}: {pr_list}")
'

